function applyLanguage(language) {
  const selected = translations[language] ? language : "en";
  const dictionary = translations[selected];
  document.documentElement.lang = selected;
  document.documentElement.dir = selected === "ar" ? "rtl" : "ltr";
  document.querySelectorAll("[data-i18n]").forEach(element => {
    const key = element.dataset.i18n;
    if (Object.prototype.hasOwnProperty.call(dictionary, key)) element.textContent = dictionary[key];
  });
  document.querySelectorAll("[data-i18n-alt]").forEach(element => {
    const key = element.dataset.i18nAlt;
    if (Object.prototype.hasOwnProperty.call(dictionary, key)) element.alt = dictionary[key];
  });
  const productLanguage = ["en", "tr", "ru", "ar"].includes(selected) ? selected : "en";
  document.querySelectorAll("[data-product-screen]").forEach(image => {
    image.src = `assets/product-screens/${image.dataset.productScreen}-${productLanguage}-safe.png`;
  });
  document.querySelectorAll("[data-language]").forEach(select => { select.value = selected; });
  localStorage.setItem("vendisyn-language", selected);
}

document.addEventListener("DOMContentLoaded", () => {
  document.querySelectorAll(".footer-links").forEach(footerLinks => {
    footerLinks.innerHTML = '<a href="contact.html" data-i18n="navContact">Contact</a>';
  });
  document.querySelectorAll(".brand").forEach(brand => {
    const logo = brand.querySelector("img");
    if (logo) logo.alt = "";
    const label = brand.querySelector("span");
    if (label) {
      label.className = "brand-copy";
      label.innerHTML = "<strong>VENDISYN</strong><small>International Patient Operations</small>";
    }
  });
  if (location.pathname.endsWith("platform.html") && !document.querySelector(".product-access")) {
    const patientFileEyebrow = document.querySelector("main .section .eyebrow");
    if (patientFileEyebrow) patientFileEyebrow.dataset.i18n = "centralEyebrow";
    const sections = document.querySelectorAll("main > section");
    const reference = sections[sections.length - 1];
    const platformReportTitle = reference.querySelector("[data-i18n='reportsTitle']");
    const platformReportText = reference.querySelector("[data-i18n='reportsText']");
    if (platformReportTitle) platformReportTitle.dataset.i18n = "platformReportsTitle";
    if (platformReportText) platformReportText.dataset.i18n = "platformReportsText";
    const access = document.createElement("section");
    access.className = "section product-access";
    access.innerHTML = `<div class="container split"><figure class="product-shot"><img src="assets/vendisyn-login.jpg" alt="VENDISYN secure login screen"></figure><div><p class="eyebrow" data-i18n="accessEyebrow">Secure access</p><h2 data-i18n="accessTitle">Every user enters an authorized operational area.</h2><p class="lead" data-i18n="accessText">Only active and authorized users can access VENDISYN.</p><ul class="feature-list"><li data-i18n="access1">Institution and hospital-scoped visibility</li><li data-i18n="access2">Role and permission-based access</li><li data-i18n="access3">Traceable user activity</li></ul></div></div>`;
    reference.before(access);
  }
  if (location.pathname.endsWith("contact.html")) {
    const contactCard = document.querySelector(".contact-card");
    if (contactCard) {
      contactCard.innerHTML = `<form class="contact-form" data-contact-form novalidate><div class="form-field"><label for="contact-name" data-i18n="formName">Full name</label><input id="contact-name" name="name" required minlength="2" maxlength="120" autocomplete="name"></div><div class="form-field"><label for="contact-organization" data-i18n="formOrganization">Hospital / organization</label><input id="contact-organization" name="organization" required minlength="2" maxlength="180" autocomplete="organization"></div><div class="form-field"><label for="contact-email" data-i18n="formEmail">Corporate e-mail</label><input id="contact-email" name="email" type="email" required maxlength="254" autocomplete="email"></div><div class="form-field"><label for="contact-phone" data-i18n="formPhone">Phone (optional)</label><input id="contact-phone" name="phone" maxlength="40" autocomplete="tel"></div><div class="form-field full"><label for="contact-message" data-i18n="formMessage">Your message</label><textarea id="contact-message" name="message" required minlength="20" maxlength="3000"></textarea></div><div class="honeypot" aria-hidden="true"><label>Website<input name="website" tabindex="-1" autocomplete="off"></label></div><input type="hidden" name="_subject" value="New VENDISYN contact request"><input type="hidden" name="turnstile_token"><div class="form-actions"><div class="turnstile-slot" data-turnstile-slot></div><button class="button" type="submit" data-i18n="formSubmit">Send request</button></div><p class="form-status full" data-form-status aria-live="polite"></p></form>`;
      setupContactForm(contactCard.querySelector("[data-contact-form]"));
    }
  }
  const homeHero = document.querySelector("main > .hero");
  if (homeHero) {
    const panel = homeHero.querySelector(".hero-panel");
    if (panel) {
      panel.classList.add("hero-proof");
      panel.innerHTML = `<p class="eyebrow" data-i18n="panelKicker">How VENDISYN delivers</p><h3 data-i18n="panelTitle">One patient. Every team. One traceable operation.</h3><p class="panel-intro" data-i18n="panelText">A shared operational structure keeps information, responsibilities and decisions connected.</p><div class="proof-list"><div class="proof-item"><span>01</span><div><strong data-i18n="proof1">Central Patient File</strong><small data-i18n="proof1t">Authorized teams work from the same patient context.</small></div></div><div class="proof-item"><span>02</span><div><strong data-i18n="proof2">Role-based work queues</strong><small data-i18n="proof2t">Each team sees its own responsibilities and pending work.</small></div></div><div class="proof-item"><span>03</span><div><strong data-i18n="proof3">Timeline &amp; Audit Log</strong><small data-i18n="proof3t">Every action, decision and hand-off remains traceable.</small></div></div></div>`;
    }
    const journey = document.querySelector(".flow")?.closest("section");
    if (journey && homeHero.nextElementSibling !== journey) homeHero.after(journey);
    const channelItems = document.querySelectorAll(".channel-list span");
    if (channelItems[1]) channelItems[1].dataset.i18n = "channelWhatsApp";
    if (channelItems[2]) channelItems[2].dataset.i18n = "channelSms";
  }
  const initial = localStorage.getItem("vendisyn-language") || "en";
  applyLanguage(initial);
  document.querySelectorAll("[data-language]").forEach(select => select.addEventListener("change", event => applyLanguage(event.target.value)));
  const menuButton = document.querySelector("[data-menu-button]");
  const menu = document.querySelector("[data-menu]");
  menuButton?.addEventListener("click", () => {
    const open = menu.classList.toggle("open");
    menuButton.setAttribute("aria-expanded", String(open));
  });
  document.querySelectorAll("[data-year]").forEach(element => { element.textContent = new Date().getFullYear(); });
});

function setupContactForm(form) {
  if (!form) return;
  const config = window.VENDISYN_CONTACT_CONFIG || {};
  const status = form.querySelector("[data-form-status]");
  const tokenInput = form.elements.turnstile_token;
  if (config.turnstileSiteKey) {
    window.vendisynTurnstileReady = () => {
      window.turnstile.render(form.querySelector("[data-turnstile-slot]"), {
        sitekey: config.turnstileSiteKey,
        callback: token => { tokenInput.value = token; }
      });
    };
    const script = document.createElement("script");
    script.src = "https://challenges.cloudflare.com/turnstile/v0/api.js?onload=vendisynTurnstileReady&render=explicit";
    script.async = true;
    script.defer = true;
    document.head.appendChild(script);
  }
  form.addEventListener("submit", async event => {
    event.preventDefault();
    if (!form.reportValidity()) return;
    const language = document.documentElement.lang || "en";
    const dictionary = translations[language] || translations.en;
    status.className = "form-status full";
    status.textContent = dictionary.formSending;
    const button = form.querySelector("button[type='submit']");
    button.disabled = true;
    try {
      const payload = Object.fromEntries(new FormData(form).entries());
      const response = await fetch(config.endpoint || "/api/v1/public/contact", { method: "POST", headers: { "Content-Type": "application/json", "Accept": "application/json" }, body: JSON.stringify(payload) });
      if (!response.ok) throw new Error("contact_request_failed");
      form.reset();
      status.className = "form-status full success";
      status.textContent = dictionary.formSuccess;
    } catch {
      status.className = "form-status full error";
      status.textContent = dictionary.formError;
    } finally {
      button.disabled = false;
    }
  });
}
